const i=[{id:"pneumonia-pleurisy-tb-001",topicId:"pneumonia-pleurisy-tb",question:"Что представляет собой пневмония?",options:["Острое поражение лёгких инфекционно-воспалительного характера","Хроническое неинфекционное воспаление дыхательных путей","Воспаление плевры с накоплением жидкости","Разрастание лимфоидной ткани в носоглотке"],correctIndex:0,explanation:"Пневмония — острое поражение лёгких инфекционно-воспалительного характера.",difficulty:"easy",tags:["пневмония","определение"]},{id:"pneumonia-pleurisy-tb-002",topicId:"pneumonia-pleurisy-tb",question:"Какие структуры преимущественно вовлекаются в процесс при пневмонии?",options:["Плевральные листки и плевральная полость","Альвеолы и ткань лёгких","Гортань и голосовые связки","Придаточные пазухи носа"],correctIndex:1,explanation:"При пневмонии вовлекаются все структурные элементы лёгочной ткани, преимущественно альвеолы и ткань лёгких.",difficulty:"medium",tags:["пневмония","патогенез"]},{id:"pneumonia-pleurisy-tb-003",topicId:"pneumonia-pleurisy-tb",question:"Для каких категорий пациентов пневмония особенно опасна?",options:["Только для детей до трёх лет","Только для людей, занятых физическим трудом","Для лиц пожилого и старческого возраста, людей с пониженным иммунитетом и хроническими заболеваниями","Только для пациентов с аллергическими заболеваниями"],correctIndex:2,explanation:"Пневмония особенно опасна для лиц пожилого и старческого возраста, людей с пониженным иммунитетом и хроническими заболеваниями.",difficulty:"medium",tags:["пневмония","группы риска"]},{id:"pneumonia-pleurisy-tb-004",topicId:"pneumonia-pleurisy-tb",question:"Может ли пневмония развиться у молодых здоровых людей?",options:["Нет, она возникает только при иммунодефиците","Нет, она встречается исключительно у пожилых","Только при наличии хронических заболеваний лёгких","Да, пневмония может возникать и у молодых, здоровых людей"],correctIndex:3,explanation:"Пневмония может возникать и у молодых, здоровых людей, хотя наиболее опасна для пожилых и ослабленных пациентов.",difficulty:"medium",tags:["пневмония","группы риска"]},{id:"pneumonia-pleurisy-tb-005",topicId:"pneumonia-pleurisy-tb",question:"Какие проявления характеризуют клинику пневмонии?",options:["Лихорадка, слабость, потливость, боль в грудной клетке, одышка, кашель с мокротой","Ночные судороги в ногах и вечерние отёки","Головная боль в затылке и шум в ушах","Зуд кожи, сыпь и чихание"],correctIndex:0,explanation:"Клиника пневмонии характеризуется лихорадкой, слабостью, потливостью, болью в грудной клетке, одышкой и кашлем с мокротой.",difficulty:"medium",tags:["пневмония","клиника"]},{id:"pneumonia-pleurisy-tb-006",topicId:"pneumonia-pleurisy-tb",question:"Какой характер может иметь мокрота при пневмонии?",options:["Только прозрачная водянистая","Слизистая, гнойная, «ржавая»","Исключительно пенистая розовая","Мокрота при пневмонии не отделяется"],correctIndex:1,explanation:"При пневмонии отмечается кашель с мокротой — слизистой, гнойной или «ржавой».",difficulty:"medium",tags:["пневмония","клиника"]},{id:"pneumonia-pleurisy-tb-007",topicId:"pneumonia-pleurisy-tb",question:"Мокрота какого необычного цвета описана как характерная для пневмонии?",options:["Зелёная","Чёрная","«Ржавая»","Ярко-алая"],correctIndex:2,explanation:"Среди вариантов мокроты при пневмонии описана «ржавая» мокрота.",difficulty:"medium",tags:["пневмония","клиника"]},{id:"pneumonia-pleurisy-tb-008",topicId:"pneumonia-pleurisy-tb",question:"После каких состояний в основном развивается пневмония?",options:["После физических перегрузок и стресса","После пищевых отравлений","После длительного приёма антибиотиков","После гриппа, переохлаждения и других воспалительных заболеваний дыхательных путей"],correctIndex:3,explanation:"Пневмония развивается в основном после гриппа, переохлаждения и других воспалительных заболеваний дыхательных путей.",difficulty:"medium",tags:["пневмония","этиология"]},{id:"pneumonia-pleurisy-tb-009",topicId:"pneumonia-pleurisy-tb",question:"Что такое плеврит?",options:["Воспаление плевры","Воспаление альвеол лёгких","Воспаление бронхов","Воспаление слизистой трахеи"],correctIndex:0,explanation:"Плеврит — воспаление плевры.",difficulty:"easy",tags:["плеврит","определение"]},{id:"pneumonia-pleurisy-tb-010",topicId:"pneumonia-pleurisy-tb",question:"Как называется жидкость, накапливающаяся в плевральной полости при плеврите?",options:["Транссудат","Экссудат","Лимфа","Сурфактант"],correctIndex:1,explanation:"При плеврите в плевральной полости накапливается жидкость — экссудат.",difficulty:"medium",tags:["плеврит","терминология"]},{id:"pneumonia-pleurisy-tb-011",topicId:"pneumonia-pleurisy-tb",question:"При какой форме плеврита в плевральной полости появляется жидкость?",options:["При сухом плеврите","При любой форме плеврита","Только при экссудативном плеврите","При туберкулёзном плеврите независимо от формы"],correctIndex:2,explanation:"Жидкость в плевральной полости появляется только при экссудативном плеврите.",difficulty:"hard",tags:["плеврит","классификация"]},{id:"pneumonia-pleurisy-tb-012",topicId:"pneumonia-pleurisy-tb",question:"Является ли плеврит самостоятельным заболеванием?",options:["Да, всегда развивается изолированно","Да, он никогда не связан с другими болезнями","Только у пациентов пожилого возраста","Редко является самостоятельным заболеванием, чаще развивается на фоне других процессов"],correctIndex:3,explanation:"Плеврит сам по себе редко является самостоятельным заболеванием — чаще он развивается на фоне других патологических процессов.",difficulty:"medium",tags:["плеврит","этиология"]},{id:"pneumonia-pleurisy-tb-013",topicId:"pneumonia-pleurisy-tb",question:"На фоне каких состояний чаще всего развивается плеврит?",options:["Заболеваний лёгких, опухолевых процессов, осложнений в плевре и воспалительных процессов в организме","Заболеваний почек и мочевыводящих путей","Эндокринных нарушений и сахарного диабета","Травм опорно-двигательного аппарата"],correctIndex:0,explanation:"Плеврит чаще развивается на фоне заболеваний лёгких (например, пневмонии), опухолевых процессов, осложнений в плевре и различных воспалительных процессов в организме.",difficulty:"medium",tags:["плеврит","этиология"]},{id:"pneumonia-pleurisy-tb-014",topicId:"pneumonia-pleurisy-tb",question:"Какое заболевание лёгких приведено как типичный фон для развития плеврита?",options:["Бронхиальная астма","Пневмония","Хронический бронхит","Эмфизема лёгких"],correctIndex:1,explanation:"В качестве примера заболевания лёгких, на фоне которого развивается плеврит, указана пневмония.",difficulty:"medium",tags:["плеврит","этиология"]},{id:"pneumonia-pleurisy-tb-015",topicId:"pneumonia-pleurisy-tb",question:"Какая бактерия вызывает туберкулёз?",options:["Streptococcus pneumoniae","Staphylococcus aureus","Mycobacterium tuberculosis","Klebsiella pneumoniae"],correctIndex:2,explanation:"Туберкулёз вызывается бактерией Mycobacterium tuberculosis.",difficulty:"medium",tags:["туберкулёз","этиология"]},{id:"pneumonia-pleurisy-tb-016",topicId:"pneumonia-pleurisy-tb",question:"Какие органы, помимо лёгких, может поражать туберкулёзная инфекция?",options:["Только органы дыхания","Только желудочно-кишечный тракт","Только органы зрения","Почки, кости и другие органы"],correctIndex:3,explanation:"Туберкулёзная инфекция может поражать не только лёгкие, но и другие органы — почки, кости и т. д.",difficulty:"medium",tags:["туберкулёз","клиника"]},{id:"pneumonia-pleurisy-tb-017",topicId:"pneumonia-pleurisy-tb",question:"Какое изменение массы тела характерно для туберкулёза?",options:["Резкое похудение","Быстрая прибавка массы тела","Масса тела не изменяется","Отёчность с увеличением веса"],correctIndex:0,explanation:"При туберкулёзе часто наблюдается резкое похудение.",difficulty:"easy",tags:["туберкулёз","симптомы"]},{id:"pneumonia-pleurisy-tb-018",topicId:"pneumonia-pleurisy-tb",question:"В какое время суток особенно выражена потливость при туберкулёзе?",options:["Днём при физической нагрузке","Ночью","Утром сразу после пробуждения","Только после приёма пищи"],correctIndex:1,explanation:"Для туберкулёза характерна ночная потливость.",difficulty:"medium",tags:["туберкулёз","симптомы"]},{id:"pneumonia-pleurisy-tb-019",topicId:"pneumonia-pleurisy-tb",question:"Какой характер имеет кашель при туберкулёзе?",options:["Приступообразный, только ночью","Однократный после физической нагрузки","Длительный","Кратковременный, проходящий за 2–3 дня"],correctIndex:2,explanation:"При туберкулёзе часто наблюдается длительный кашель.",difficulty:"easy",tags:["туберкулёз","симптомы"]},{id:"pneumonia-pleurisy-tb-020",topicId:"pneumonia-pleurisy-tb",question:"Как называется показатель насыщения крови кислородом?",options:["Гематокрит","Гемоглобин","Сурфактант","Сатурация"],correctIndex:3,explanation:"Показатель насыщения крови кислородом называется сатурацией.",difficulty:"easy",tags:["сатурация","терминология"]},{id:"pneumonia-pleurisy-tb-021",topicId:"pneumonia-pleurisy-tb",question:"Каким символом обозначается сатурация?",options:["SpO₂","PaCO₂","HGB","FEV₁"],correctIndex:0,explanation:"Сатурация обозначается как SpO₂ и измеряется в процентах.",difficulty:"medium",tags:["сатурация","терминология"]},{id:"pneumonia-pleurisy-tb-022",topicId:"pneumonia-pleurisy-tb",question:"Какие значения сатурации считаются нормальными?",options:["80–90%","94–100%","90–94%","70–85%"],correctIndex:1,explanation:"Нормой сатурации считаются значения 94–100%.",difficulty:"medium",tags:["сатурация","нормы"]},{id:"pneumonia-pleurisy-tb-023",topicId:"pneumonia-pleurisy-tb",question:"Какому диапазону SpO₂ соответствует среднее значение сатурации?",options:["94–100%","85–90%","90–94%","Ниже 80%"],correctIndex:2,explanation:"Средним значением сатурации считается диапазон 90–94%.",difficulty:"medium",tags:["сатурация","нормы"]},{id:"pneumonia-pleurisy-tb-024",topicId:"pneumonia-pleurisy-tb",question:"Начиная с какого уровня сатурация считается сниженной?",options:["Ниже 100%","Ниже 98%","Ниже 94%","Ниже 90%"],correctIndex:3,explanation:"Сниженной считается сатурация ниже 90%.",difficulty:"medium",tags:["сатурация","нормы"]},{id:"pneumonia-pleurisy-tb-025",topicId:"pneumonia-pleurisy-tb",question:"Что обозначает термин «гипоксия»?",options:["Уменьшение количества кислорода в крови","Полную остановку дыхания","Острую дыхательную недостаточность","Учащение частоты дыхания"],correctIndex:0,explanation:"Гипоксия — уменьшение количества кислорода в крови.",difficulty:"easy",tags:["терминология","нарушения дыхания"]},{id:"pneumonia-pleurisy-tb-026",topicId:"pneumonia-pleurisy-tb",question:"Какое состояние определяется как острая дыхательная недостаточность?",options:["Гипоксия","Асфиксия","Апноэ","Брадипноэ"],correctIndex:1,explanation:"Асфиксия — это острая дыхательная недостаточность.",difficulty:"medium",tags:["терминология","нарушения дыхания"]},{id:"pneumonia-pleurisy-tb-027",topicId:"pneumonia-pleurisy-tb",question:"Каким термином обозначается полная остановка дыхания?",options:["Тахипноэ","Гипоксия","Апноэ","Асфиксия"],correctIndex:2,explanation:"Апноэ — полная остановка дыхания.",difficulty:"medium",tags:["терминология","нарушения дыхания"]},{id:"pneumonia-pleurisy-tb-028",topicId:"pneumonia-pleurisy-tb",question:"Какова нормальная частота дыхания у взрослого человека в спокойном состоянии?",options:["8–12 дыхательных движений в минуту","12–16 дыхательных движений в минуту","20–30 дыхательных движений в минуту","16–20 дыхательных движений в минуту"],correctIndex:3,explanation:"Нормальная частота дыхания у взрослого человека в спокойном состоянии составляет 16–20 дыхательных движений в минуту.",difficulty:"medium",tags:["нормы","физиология"]},{id:"pneumonia-pleurisy-tb-029",topicId:"pneumonia-pleurisy-tb",question:"Как называется учащённое дыхание?",options:["Тахипноэ","Брадипноэ","Апноэ","Асфиксия"],correctIndex:0,explanation:"Тахипноэ — учащённое дыхание, то есть повышение частоты дыхания.",difficulty:"easy",tags:["терминология","нарушения дыхания"]},{id:"pneumonia-pleurisy-tb-030",topicId:"pneumonia-pleurisy-tb",question:"Уменьшение частоты дыхательных движений обозначается термином:",options:["Тахипноэ","Брадипноэ","Гипоксия","Апноэ"],correctIndex:1,explanation:"Брадипноэ — замедленное дыхание, то есть уменьшение частоты дыхания.",difficulty:"easy",tags:["терминология","нарушения дыхания"]},{id:"pneumonia-pleurisy-tb-031",topicId:"pneumonia-pleurisy-tb",question:"Как называется метод диагностики, представляющий собой прослушивание лёгких?",options:["Перкуссия","Пальпация","Аускультация","Бронхоскопия"],correctIndex:2,explanation:"Аускультация — прослушивание лёгких, один из методов диагностики заболеваний дыхательной системы.",difficulty:"medium",tags:["диагностика"]},{id:"pneumonia-pleurisy-tb-032",topicId:"pneumonia-pleurisy-tb",question:"Какой эндоскопический метод входит в диагностику заболеваний дыхательной системы?",options:["Гастроскопия","Колоноскопия","Цистоскопия","Бронхоскопия"],correctIndex:3,explanation:"Бронхоскопия входит в перечень методов диагностики заболеваний дыхательной системы.",difficulty:"medium",tags:["диагностика"]},{id:"pneumonia-pleurisy-tb-033",topicId:"pneumonia-pleurisy-tb",question:"Какие лучевые методы применяются для диагностики заболеваний органов дыхания?",options:["Рентгенография, КТ и МРТ","Электрокардиография и эхокардиография","Спирометрия и пикфлоуметрия","Допплерография и ангиография"],correctIndex:0,explanation:"Для диагностики заболеваний дыхательной системы применяются рентгенография, компьютерная томография (КТ) и магнитно-резонансная томография (МРТ).",difficulty:"medium",tags:["диагностика"]},{id:"pneumonia-pleurisy-tb-034",topicId:"pneumonia-pleurisy-tb",question:"Как расшифровывается аббревиатура МРТ?",options:["Механическая респираторная терапия","Магнитно-резонансная томография","Многослойная рентгеновская томограмма","Мониторинг работы трахеи"],correctIndex:1,explanation:"МРТ — магнитно-резонансная томография, один из методов диагностики заболеваний дыхательной системы.",difficulty:"easy",tags:["диагностика","терминология"]},{id:"pneumonia-pleurisy-tb-035",topicId:"pneumonia-pleurisy-tb",question:"Какая группа препаратов, применяемых при заболеваниях органов дыхания, обладает бронхорасширяющим действием?",options:["Антигистаминные препараты","Противокашлевые средства","Бронходилататоры","Кортикостероиды"],correctIndex:2,explanation:"Бронходилататоры — это бронхорасширяющие средства, применяемые при заболеваниях органов дыхания.",difficulty:"easy",tags:["лечение","классификация"]},{id:"pneumonia-pleurisy-tb-036",topicId:"pneumonia-pleurisy-tb",question:"Какое второе название имеют кортикостероиды в перечне препаратов для лечения болезней дыхательной системы?",options:["Бронходилататоры","Муколитики","Антигистаминные средства","Глюкокортикоиды"],correctIndex:3,explanation:"Кортикостероиды в перечне препаратов указаны как глюкокортикоиды.",difficulty:"medium",tags:["лечение","классификация"]},{id:"pneumonia-pleurisy-tb-037",topicId:"pneumonia-pleurisy-tb",question:"Против чего применяются антигистаминные препараты при заболеваниях органов дыхания?",options:["Против аллергии","Против бактериальной инфекции","Против вязкой мокроты","Против спазма бронхов"],correctIndex:0,explanation:"Антигистаминные препараты применяются против аллергии.",difficulty:"easy",tags:["лечение","классификация"]},{id:"pneumonia-pleurisy-tb-038",topicId:"pneumonia-pleurisy-tb",question:"Какие средства входят в группу противоинфекционных препаратов при болезнях дыхательной системы?",options:["Только антибактериальные препараты","Антибактериальные, противогрибковые и противовирусные","Только противовирусные препараты","Только противогрибковые препараты"],correctIndex:1,explanation:"Противоинфекционные средства включают антибактериальные, противогрибковые, противовирусные и другие препараты.",difficulty:"medium",tags:["лечение","классификация"]},{id:"pneumonia-pleurisy-tb-039",topicId:"pneumonia-pleurisy-tb",question:"Сколько групп препаратов перечислено для лечения заболеваний дыхательной системы?",options:["Три","Четыре","Пять","Семь"],correctIndex:2,explanation:"Перечислено пять групп: бронходилататоры, кортикостероиды, антигистаминные, противокашлевые и противоинфекционные средства.",difficulty:"medium",tags:["лечение","классификация"]},{id:"pneumonia-pleurisy-tb-040",topicId:"pneumonia-pleurisy-tb",question:"Какая группа препаратов применяется для подавления кашля при заболеваниях органов дыхания?",options:["Бронходилататоры","Кортикостероиды","Противоинфекционные средства","Противокашлевые средства"],correctIndex:3,explanation:"Противокашлевые средства входят в число групп препаратов, применяемых при заболеваниях органов дыхания.",difficulty:"easy",tags:["лечение","классификация"]}];export{i as default};
